import torch

from detect.detect_base import DetectBase


class SDCDetect(DetectBase):
    DETECT_TYPE = "sdc"
    SUB_DETECT_TYPE = "sdc"

    def __init__(self):
        super().__init__()

    def core_detect(self, current_output, baseline):
        return torch.any(current_output != baseline)
